var publish = new ArcActionButton
{
    Label = "Publish",
    PendingLabel = "Publishing",
    SuccessLabel = "Published",
    ResetAfterMs = 2400,
    OnAction = () => PublishAsync(),
    OnActionError = error => ShowError(error)
};

// Pending 期间按钮不禁用：键盘焦点留在原位，读屏读到 busy。
// 失败时会自己回到 Idle，OnActionError 负责把错误告知页面。
